struct ami { pthread_mutex_t m; pthread_cond_t cv; int done; long result; };
static void *run(void *arg) {
    struct ami *a = arg;
    long v = do_long_work();                      /* the deferred call */
    pthread_mutex_lock(&a->m); a->result = v; a->done = 1;
    pthread_cond_broadcast(&a->cv); pthread_mutex_unlock(&a->m);
    return NULL;
}
struct ami a = { PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0, 0 };
pthread_t th; pthread_create(&th, NULL, run, &a);      /* returns immediately */
/* later: */ pthread_mutex_lock(&a.m);
while (!a.done) pthread_cond_wait(&a.cv, &a.m);
long v = a.result; pthread_mutex_unlock(&a.m); pthread_join(th, NULL);

